#[path = "solution.rs"]
mod solution;

use solution::{Camera2D, CameraError, Vec2};

fn close(actual: f64, expected: f64) {
    assert!((actual - expected).abs() < 1e-10, "actual={actual}, expected={expected}");
}

fn matrix_close(actual: [[f64; 3]; 3], expected: [[f64; 3]; 3]) {
    for row in 0..3 {
        for column in 0..3 {
            close(actual[row][column], expected[row][column]);
        }
    }
}

#[test]
fn view_and_projection_matrices_follow_the_stated_order() {
    let camera = Camera2D::new(
        Vec2 { x: 3.0, y: 4.0 },
        std::f64::consts::FRAC_PI_2,
        2.0,
        8.0,
        10.0,
    ).unwrap();

    matrix_close(camera.view_matrix(), [
        [0.0, 2.0, -8.0],
        [-2.0, 0.0, 6.0],
        [0.0, 0.0, 1.0],
    ]);
    matrix_close(camera.projection_matrix(), [
        [0.25, 0.0, 0.0],
        [0.0, 0.2, 0.0],
        [0.0, 0.0, 1.0],
    ]);
}

#[test]
fn world_from_ndc_inverts_projection_and_view_even_outside_ndc_range() {
    let camera = Camera2D::new(
        Vec2 { x: 10.0, y: -2.0 },
        std::f64::consts::FRAC_PI_2,
        2.0,
        8.0,
        6.0,
    ).unwrap();

    let center = camera.world_from_ndc(Vec2 { x: 0.0, y: 0.0 });
    close(center.x, 10.0);
    close(center.y, -2.0);

    let outside = camera.world_from_ndc(Vec2 { x: 2.0, y: -3.0 });
    close(outside.x, 5.5);
    close(outside.y, -6.0);
}

#[test]
fn construction_rejects_every_invalid_parameter_class() {
    let valid = Vec2 { x: 0.0, y: 0.0 };
    let cases = [
        Camera2D::new(Vec2 { x: f64::NAN, y: 0.0 }, 0.0, 1.0, 1.0, 1.0),
        Camera2D::new(Vec2 { x: 0.0, y: f64::INFINITY }, 0.0, 1.0, 1.0, 1.0),
        Camera2D::new(valid, f64::NEG_INFINITY, 1.0, 1.0, 1.0),
        Camera2D::new(valid, 0.0, 0.0, 1.0, 1.0),
        Camera2D::new(valid, 0.0, -1.0, 1.0, 1.0),
        Camera2D::new(valid, 0.0, f64::NAN, 1.0, 1.0),
        Camera2D::new(valid, 0.0, 1.0, 0.0, 1.0),
        Camera2D::new(valid, 0.0, 1.0, 1.0, f64::INFINITY),
    ];
    for result in cases {
        assert!(matches!(result, Err(CameraError::InvalidParameter)));
    }
}

#[test]
fn invalid_updates_are_atomic() {
    let mut camera = Camera2D::new(Vec2 { x: 1.0, y: 2.0 }, 0.25, 3.0, 8.0, 6.0).unwrap();
    let original_view = camera.view_matrix();
    let original_projection = camera.projection_matrix();
    let original_world = camera.world_from_ndc(Vec2 { x: 0.5, y: -0.5 });

    assert!(matches!(camera.set_pose(Vec2 { x: 99.0, y: 88.0 }, 1.0, 0.0), Err(CameraError::InvalidParameter)));
    matrix_close(camera.view_matrix(), original_view);
    matrix_close(camera.projection_matrix(), original_projection);

    assert!(matches!(camera.resize(20.0, f64::NAN), Err(CameraError::InvalidParameter)));
    matrix_close(camera.view_matrix(), original_view);
    matrix_close(camera.projection_matrix(), original_projection);
    let world = camera.world_from_ndc(Vec2 { x: 0.5, y: -0.5 });
    close(world.x, original_world.x);
    close(world.y, original_world.y);
}

#[test]
fn valid_updates_replace_pose_and_dimensions() {
    let mut camera = Camera2D::new(Vec2 { x: 0.0, y: 0.0 }, 0.0, 1.0, 2.0, 2.0).unwrap();
    camera.set_pose(Vec2 { x: -3.0, y: 5.0 }, 0.0, 2.0).unwrap();
    camera.resize(4.0, 8.0).unwrap();

    matrix_close(camera.view_matrix(), [
        [2.0, 0.0, 6.0],
        [0.0, 2.0, -10.0],
        [0.0, 0.0, 1.0],
    ]);
    matrix_close(camera.projection_matrix(), [
        [0.5, 0.0, 0.0],
        [0.0, 0.25, 0.0],
        [0.0, 0.0, 1.0],
    ]);
}

